 const selected=(picked[view]??[]).filter(id=>view==='dishes'||graph.currentUses(id).length>0),heldIds=held[view]??[];
 const scope=view==='dishes'?(selection.scope??'current'):'current';
 const canEdit=!!(menu.canOrdinaryEdit&&nb?.loaded),manage=!!(menu.canEdit&&nb?.canManage),blocked=!!(!nb?.loaded||nb.loading||nb.saving||nb.operating||nb.operationPending||nb.savePending||nb.preparationBusy||busy);
 const allRows:Row[]=view==='dishes'?menu.recipes.map(recipe=>{const dish=menu.dishes.find(d=>d.id===recipe.menuId)!;return {id:recipe.id,name:dish.name,variant:recipe.variant,category:dish.category,inputs:recipe.inputs,state:graph.recipes.get(recipe.id),active:graph.activeIds.has(recipe.id),recipe};}):menu.items.filter(item=>graph.currentUses(item.id).length>0&&(!selection.checkedOnly||checkedIds.has(item.id))&&(selection.checkedOnly||item.kind===(view==='house-made'?'prep':'bought'))).map(item=>({id:item.id,name:item.name,inputs:item.composition.inputs,state:graph.states.get(item.id),active:graph.currentUses(item.id).length>0,item}));
 const matches=(row:Row)=>{const q=selection.query??'';const inScope=scope==='all'?(!row.recipe||menu.dishes.find(d=>d.id===row.recipe!.menuId)?.state!=='archived'):scope==='archived'?!!row.recipe&&menu.dishes.find(d=>d.id===row.recipe!.menuId)?.state==='archived':scope==='off'?!row.active:row.active;
  return inScope&&(row.recipe?compositionMatches(menu,row.recipe,q):normalizeName([row.name,...row.item!.aliases].join(' ')).includes(normalizeName(q)))&&(category==='all'||!row.recipe||row.category===category)&&(view==='ingredients'||filter==='all'||filter==='attention'&&!row.state?.complete||filter==='own'&&!row.state?.ownConfirmed||filter==='complete'&&row.state?.complete||filter==='empty'&&!row.inputs.length||filter==='confirmed'&&row.state?.ownConfirmed);};
